from typing import List

def subsequences(a: int, b: int, k: int) -> List[List[int]]:
    if k == 0:
        return []

    ret = []
    for i in range(a, b + 1 - k):
        ret.extend(
            [i] + rest for rest in subsequences(i + 1, b, k - 1)
        )

